  ($str$variable$str$, 'USA', $str$2026-2MoldMolding$str$, $str$cadModelMisalignmentSensitivity$str$, $str$82$str$, NULL, $str$The sensitivity level, 0-100, to CAD model misalignment$str$, $jsonb${"Variable Name":"cadModelMisalignmentSensitivity","String Value":82,"Unit Type Name":null,"Notes":"The sensitivity level, 0-100, to CAD model misalignment"}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-2MoldMolding$str$, $str$disableInvestmentAmortization$str$, $str$false$str$, NULL, $str$User override to disable amortization of all fixed costs to the individual part or assembly. By default, fixed costs are calculated per part for tooling, fixtures, and programming.$str$, $jsonb${"Variable Name":"disableInvestmentAmortization","String Value":false,"Unit Type Name":null,"Notes":"User override to disable amortization of all fixed costs to the individual part or assembly. By default, fixed costs are calculated per part for tooling, fixtures, and programming."}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-2MoldMolding$str$, $str$gearQualityDefaultAgmaNewStd$str$, $str$A8$str$, NULL, $str$A2, A3, A4, ... A11, A12$str$, $jsonb${"Variable Name":"gearQualityDefaultAgmaNewStd","String Value":"A8","Unit Type Name":null,"Notes":"A2, A3, A4, ... A11, A12"}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-2MoldMolding$str$, $str$gearQualityDefaultAgmaOldStd$str$, $str$Q8$str$, NULL, $str$Q15, Q14, Q13, ... Q6, Q5$str$, $jsonb${"Variable Name":"gearQualityDefaultAgmaOldStd","String Value":"Q8","Unit Type Name":null,"Notes":"Q15, Q14, Q13, ... Q6, Q5"}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-2MoldMolding$str$, $str$gearQualityDefaultDinStd$str$, $str$9$str$, NULL, $str$2, 3, 4, ... 11, 12$str$, $jsonb${"Variable Name":"gearQualityDefaultDinStd","String Value":9,"Unit Type Name":null,"Notes":"2, 3, 4, ... 11, 12"}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-2MoldMolding$str$, $str$overheadRateAdjustmentFactor$str$, $str$1$str$, NULL, $str$Factor used to globally increase or decrease overhead rate per process.$str$, $jsonb${"Variable Name":"overheadRateAdjustmentFactor","String Value":1,"Unit Type Name":null,"Notes":"Factor used to globally increase or decrease overhead rate per process."}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-2MoldMolding$str$, $str$rollupSourceCostsInCategories$str$, $str$true$str$, NULL, $str$'true' or 'false'. true: source component costs roll up into unique cost summary fields. false: source component Piece Part Cost or Fully Burdened Cost rolls up into material cost based on useSourceModelFBCAsMaterialCost setting.$str$, $jsonb${"Variable Name":"rollupSourceCostsInCategories","String Value":true,"Unit Type Name":null,"Notes":"'true' or 'false'. true: source component costs roll up into unique cost summary fields. false: source component Piece Part Cost or Fully Burdened Cost rolls up into material cost based on useSourceModelFBCAsMaterialCost setting."}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-2MoldMolding$str$, $str$supportsDTC$str$, $str$true$str$, NULL, $str$reference export baseline$str$, $jsonb${"Variable Name":"supportsDTC","String Value":true,"Unit Type Name":null,"Notes":"reference export baseline"}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-2MoldMolding$str$, $str$useSourceModelFBCAsMaterialCost$str$, $str$true$str$, NULL, $str$'true' or 'false'. User override to determine source model cost for material cost in 2-Model Machining. true: the Fully Burdened Cost will be used. false: the Piece Part Cost will be used. If rollupSourceCostsInCategories is true, then useSourceModelFBCAsMaterialCost has no impact.$str$, $jsonb${"Variable Name":"useSourceModelFBCAsMaterialCost","String Value":true,"Unit Type Name":null,"Notes":"'true' or 'false'. User override to determine source model cost for material cost in 2-Model Machining. true: the Fully Burdened Cost will be used. false: the Piece Part Cost will be used. If rollupSourceCostsInCategories is true, then useSourceModelFBCAsMaterialCost has no impact."}$jsonb$::jsonb),
